#!/usr/bin/env bash
# Sonar server setup. Generated by the Sonar app for one profile; safe to run again.
#
#   sudo bash install.sh              install or repair (same secrets every time)
#   sudo sonar-server --status        show the status table
#   sudo sonar-server --uninstall     remove everything this script added
#
# It installs a small local endpoint (reachable only from the server itself, no new public port) plus the Sonar
# helper, applies the network settings Sonar needs, and allows Sonar in the server firewall. It does not touch
# x-ui, SSH or any other service.
set -uo pipefail

SONAR_SCRIPTS_VERSION=__SCRIPTS_VERSION__
PROFILE_ID="__PROFILE_ID__"
HY_PORT_DEFAULT=2095
ETC=/etc/sonar
LIB=/usr/local/lib/sonar
SELF=/usr/local/sbin/sonar-server
SYSCTL_FILE=/etc/sysctl.d/99-zz-sonar-icmp.conf
FW_COMMENT="sonar-icmp"

HY_PASSWORD='__HY_PASSWORD__'
OBFS_PASSWORD='__OBFS_PASSWORD__'
CERT_B64='__CERT_PEM_B64__'
KEY_B64='__KEY_PEM_B64__'
RELAY_B64='__RELAY_PY_B64__'

TOTAL=7
step() { printf '\n[%s/%s] %s\n' "$1" "$TOTAL" "$2"; }
info() { printf '      %s\n' "$*"; }
fail() {
  printf '\nSONAR-ERROR: %s\n' "$1"
  [ -n "${2:-}" ] && printf 'FIX: %s\n' "$2"
  exit 1
}
CHANGES=()
changed() { CHANGES+=("$*"); }

need_root() {
  [ "$(id -u)" -eq 0 ] || fail "This script must run as root." "Run it again with sudo in front."
}

detect_os() {
  OS_ID=unknown; OS_LIKE=""; OS_NAME=unknown
  if [ -r /etc/os-release ]; then
    . /etc/os-release
    OS_ID="${ID:-unknown}"; OS_LIKE="${ID_LIKE:-}"; OS_NAME="${PRETTY_NAME:-$OS_ID}"
  fi
  ARCH="$(uname -m)"
  case "$ARCH" in
    x86_64|amd64) ARCH=amd64 ;;
    aarch64|arm64) ARCH=arm64 ;;
    *) fail "This CPU type ($ARCH) is not supported." "Use a server with an amd64 or arm64 CPU." ;;
  esac
  if command -v apt-get >/dev/null 2>&1; then PKG=apt
  elif command -v dnf >/dev/null 2>&1; then PKG=dnf
  elif command -v yum >/dev/null 2>&1; then PKG=yum
  else PKG=none; fi
  command -v systemctl >/dev/null 2>&1 || fail "This server has no systemd." "Use Ubuntu 20.04+ or Debian 11+."
}

wait_apt_lock() {
  local i=0
  while fuser /var/lib/dpkg/lock-frontend /var/lib/apt/lists/lock >/dev/null 2>&1; do
    [ $i -eq 0 ] && info "Waiting for another package install to finish (automatic updates)..."
    i=$((i + 1))
    [ $i -gt 120 ] && fail "The package manager is busy (apt lock held for over 10 minutes)." \
      "Wait a few minutes or reboot the server, then run the command again."
    sleep 5
  done
}

pkg_install() {
  case "$PKG" in
    apt)
      wait_apt_lock
      DEBIAN_FRONTEND=noninteractive apt-get update -qq </dev/null >/dev/null 2>&1
      DEBIAN_FRONTEND=noninteractive apt-get install -y -qq "$@" </dev/null >/dev/null 2>&1 ;;
    dnf) dnf install -y -q "$@" </dev/null >/dev/null 2>&1 ;;
    yum) yum install -y -q "$@" </dev/null >/dev/null 2>&1 ;;
    *) return 1 ;;
  esac
}

# Prints the process name holding a UDP port, or nothing.
udp_holder() {
  ss -H -ulpn "sport = :$1" 2>/dev/null | sed -n 's/.*users:(("\([^"]*\)".*/\1/p' | head -1
}

firewall_kind() {
  if command -v ufw >/dev/null 2>&1 && ufw status 2>/dev/null | grep -q '^Status: active'; then echo ufw
  elif command -v firewall-cmd >/dev/null 2>&1 && firewall-cmd --state >/dev/null 2>&1; then echo firewalld
  elif command -v iptables >/dev/null 2>&1; then echo iptables
  else echo none; fi
}

iptables_rule() { iptables "$1" INPUT ${2:-} -p icmp --icmp-type echo-request -m comment --comment "$FW_COMMENT" -j ACCEPT; }

firewall_open() {
  FW="$(firewall_kind)"
  case "$FW" in
    ufw)
      if grep -qE '^-A ufw-before-input -p icmp --icmp-type echo-request -j ACCEPT' /etc/ufw/before.rules 2>/dev/null; then
        info "ufw already allows ping (echo-request) in /etc/ufw/before.rules."
      else
        iptables_rule -C 2>/dev/null || { iptables_rule -I 1; changed "firewall: allowed Sonar at the top of INPUT (ufw)"; }
        persist_iptables
      fi ;;
    firewalld)
      if firewall-cmd --query-icmp-block=echo-request >/dev/null 2>&1; then
        firewall-cmd --permanent --remove-icmp-block=echo-request >/dev/null && firewall-cmd --reload >/dev/null
        changed "firewall: allowed Sonar (firewalld)"
      fi
      if firewall-cmd --query-icmp-block-inversion >/dev/null 2>&1; then
        info "Note: firewalld uses icmp-block-inversion; check that echo-request is allowed."
      fi ;;
    iptables)
      # Insert at the top so it sits before any final REJECT (some cloud images) and before rules added by panels (x-ui).
      if ! iptables_rule -C 2>/dev/null; then
        iptables_rule -I 1
        changed "firewall: allowed Sonar at the top of INPUT"
      else
        case "$(iptables -S INPUT 2>/dev/null | sed -n 2p)" in
          *"$FW_COMMENT"*) ;;
          *) iptables_rule -D; iptables_rule -I 1
             changed "firewall: moved the Sonar rule to the top of INPUT" ;;
        esac
      fi
      persist_iptables ;;
    *)
      info "No firewall tool found; assuming nothing on the server blocks ping." ;;
  esac
}

persist_iptables() {
  if command -v netfilter-persistent >/dev/null 2>&1; then
    netfilter-persistent save >/dev/null 2>&1 && return
  fi
  if [ "$PKG" = apt ]; then
    echo iptables-persistent iptables-persistent/autosave_v4 boolean true | debconf-set-selections 2>/dev/null
    echo iptables-persistent iptables-persistent/autosave_v6 boolean true | debconf-set-selections 2>/dev/null
    pkg_install iptables-persistent && changed "installed iptables-persistent (keeps firewall rules after reboot)"
    command -v netfilter-persistent >/dev/null 2>&1 && netfilter-persistent save >/dev/null 2>&1 && return
  fi
  if command -v service >/dev/null 2>&1 && service iptables save >/dev/null 2>&1; then return; fi
  info "Note: could not save the firewall rule permanently; it is active until the next reboot (run this command again after a reboot)."
}

firewall_close() {
  if command -v iptables >/dev/null 2>&1; then
    local n=0
    while iptables_rule -D 2>/dev/null; do n=$((n + 1)); done
    if [ $n -gt 0 ]; then
      command -v netfilter-persistent >/dev/null 2>&1 && netfilter-persistent save >/dev/null 2>&1
      echo "removed the Sonar iptables rule (ping stays allowed if another rule allows it)"
    fi
  fi
}

sysctl_on() {
  printf '# managed by Sonar\nnet.ipv4.icmp_echo_ignore_all = 1\n' > "$SYSCTL_FILE"
  if [ "$(sysctl -n net.ipv4.icmp_echo_ignore_all 2>/dev/null)" != 1 ]; then
    sysctl -q -w net.ipv4.icmp_echo_ignore_all=1 || fail "Could not set net.ipv4.icmp_echo_ignore_all=1." "This VPS type may not allow kernel settings (some containers). Use a full VM."
    changed "applied network settings (saved in $SYSCTL_FILE)"
  fi
  # Warn when a later file would undo it at boot.
  local f
  for f in /etc/sysctl.conf /run/sysctl.d/*.conf /usr/lib/sysctl.d/*.conf; do
    [ -f "$f" ] && grep -qE '^[[:space:]]*net\.ipv4\.icmp_echo_ignore_all[[:space:]]*=[[:space:]]*0' "$f" && \
      info "Note: $f sets icmp_echo_ignore_all=0; Sonar's file is read after it, so Sonar's value wins."
  done
}

# Sends one tunnel poll to the local relay over loopback and reports who answered:
#   relay  = the Sonar relay answered (correct)   kernel = the kernel echoed it (sysctl not applied)   none
self_probe() {
  python3 -I - <<'PY' 2>/dev/null
import os, socket, struct, time
def ck(b):
    if len(b) % 2: b += b"\0"
    s = sum(struct.unpack("!%dH" % (len(b) // 2), b)); s = (s >> 16) + (s & 0xFFFF); s += s >> 16
    return ~s & 0xFFFF
r = socket.socket(socket.AF_INET, socket.SOCK_RAW, socket.IPPROTO_ICMP); r.settimeout(0.3)
ident = 0x5350; seen = "none"
for seq in range(1, 6):
    pl = b"RT\x00" + b"\0" * 5 + struct.pack("!H", seq) + b"\0" * 54
    h = struct.pack("!BBHHH", 8, 0, 0, ident, seq)
    r.sendto(struct.pack("!BBHHH", 8, 0, ck(h + pl), ident, seq) + pl, ("127.0.0.1", 0))
    end = time.time() + 0.6
    while time.time() < end:
        try:
            d, _ = r.recvfrom(65535)
        except socket.timeout:
            continue
        ip = (d[0] & 15) * 4
        if len(d) < ip + 8 or d[ip] != 0: continue
        i, s = struct.unpack("!HH", d[ip + 4:ip + 8])
        if i != ident or s != seq: continue
        p = d[ip + 8:]
        if p == pl: seen = "kernel"
        elif p[:2] == b"RT": seen = "relay"; break
    if seen == "relay": break
print(seen)
PY
}

status_table() {
  local hy_port ok_all=1 hy=FAIL relay=FAIL sc=FAIL fw=FAIL st=FAIL relay_ver="" probe hyflag=0
  hy_port="$(cat "$ETC/hy_port" 2>/dev/null || echo "$HY_PORT_DEFAULT")"
  systemctl is-active --quiet sonar-edge && [ -n "$(udp_holder "$hy_port")" ] && { hy=OK; hyflag=1; }
  systemctl is-active --quiet sonar-link && relay=OK
  relay_ver="$(python3 -I "$LIB/sonar_link.py" --version 2>/dev/null)"
  [ "$(sysctl -n net.ipv4.icmp_echo_ignore_all 2>/dev/null)" = 1 ] && [ -f "$SYSCTL_FILE" ] && sc=OK
  case "$(firewall_kind)" in
    ufw) { grep -qE '^-A ufw-before-input -p icmp --icmp-type echo-request -j ACCEPT' /etc/ufw/before.rules 2>/dev/null || iptables_rule -C 2>/dev/null; } && fw=OK ;;
    firewalld) firewall-cmd --query-icmp-block=echo-request >/dev/null 2>&1 || fw=OK ;;
    iptables) iptables_rule -C 2>/dev/null && fw=OK ;;
    none) fw=OK ;;
  esac
  probe="$(self_probe)"
  [ "$probe" = relay ] && st=OK
  echo
  echo "==== Sonar server status ===="
  printf '%-5s %-10s %s\n' "$hy"    endpoint  "Endpoint on 127.0.0.1:${hy_port} (local only)"
  printf '%-5s %-10s %s\n' "$relay" helper    "Sonar helper, version ${relay_ver:-?}"
  printf '%-5s %-10s %s\n' "$sc"    network   "network settings applied and saved"
  printf '%-5s %-10s %s\n' "$fw"    firewall  "Sonar allowed ($(firewall_kind))"
  printf '%-5s %-10s %s\n' "$st"    self-test "Sonar answers on this server (by: ${probe:-none})"
  for x in "$hy" "$relay" "$sc" "$fw" "$st"; do [ "$x" = OK ] || ok_all=0; done
  local result=fail; [ $ok_all = 1 ] && result=ok
  echo "SONAR-STATUS: result=$result profile=$(cat "$ETC/profile" 2>/dev/null) scripts=$(cat "$ETC/version" 2>/dev/null) relay=${relay_ver:-0} hy=$hyflag sysctl=$([ $sc = OK ] && echo 1 || echo 0) fw=$(firewall_kind) probe=${probe:-none}"
  if [ $ok_all = 1 ]; then
    echo "All good. The server side is ready. Go back to the Sonar app."
  else
    echo "Something is not right. Copy everything above and paste it into the Sonar app."
  fi
  [ $ok_all = 1 ]
}

uninstall() {
  need_root
  echo "Removing Sonar from this server..."
  for s in sonar-link sonar-edge; do
    systemctl disable --now "$s" >/dev/null 2>&1 && echo "stopped and disabled $s"
    rm -f "/etc/systemd/system/$s.service"
  done
  systemctl daemon-reload
  firewall_close
  if [ -f "$SYSCTL_FILE" ]; then
    rm -f "$SYSCTL_FILE"
    sysctl -q -w net.ipv4.icmp_echo_ignore_all=0 && echo "reverted network settings (removed $SYSCTL_FILE)"
  fi
  rm -rf "$ETC" "$LIB" && echo "removed $ETC and $LIB"
  id sonar >/dev/null 2>&1 && userdel sonar >/dev/null 2>&1 && echo "removed system user sonar"
  echo "Left in place: /usr/local/bin/hysteria (the Hysteria2 program, may be used by other setups)."
  echo "To remove it too: bash <(curl -fsSL https://get.hy2.sh/) --remove"
  rm -f "$SELF"
  echo "Done. Sonar is removed from this server."
}

install() {
  need_root
  echo "Sonar server setup (scripts v${SONAR_SCRIPTS_VERSION})"

  step 1 "Checking this server"
  detect_os
  info "System: $OS_NAME ($ARCH)"
  case "$OS_ID $OS_LIKE" in
    *ubuntu*|*debian*) ;;
    *) info "Note: tested on Ubuntu and Debian. Continuing on $OS_ID (best effort)." ;;
  esac
  if [ -f "$ETC/profile" ] && [ "$(cat "$ETC/profile")" != "$PROFILE_ID" ]; then
    info "Replacing a previous Sonar setup on this server with this profile."
  fi
  systemctl list-unit-files 2>/dev/null | grep -q '^x-ui' && info "x-ui found: it is left untouched."
  if systemctl is-active --quiet icmp-relay 2>/dev/null; then
    fail "Another helper (icmp-relay.service) is already running on this server." \
      "Stop it first: sudo systemctl disable --now icmp-relay , then run this command again."
  fi

  step 2 "Installing python3, curl and iproute2 (if missing)"
  missing=()
  command -v python3 >/dev/null 2>&1 || missing+=(python3)
  command -v curl >/dev/null 2>&1 || missing+=(curl)
  command -v ss >/dev/null 2>&1 || missing+=(iproute2)
  if [ ${#missing[@]} -gt 0 ]; then
    [ "$PKG" = apt ] || [ "$PKG" = dnf ] || [ "$PKG" = yum ] || fail "No package manager found to install ${missing[*]}." "Install ${missing[*]} by hand, then run the command again."
    [ "$PKG" != apt ] && missing=("${missing[@]/iproute2/iproute}")
    pkg_install "${missing[@]}" || fail "Could not install ${missing[*]}." "Run: sudo apt-get update && sudo apt-get install -y ${missing[*]} , then run the command again."
    changed "installed packages: ${missing[*]}"
  fi
  info "python3 $(python3 -c 'import sys;print("%d.%d"%sys.version_info[:2])')"

  step 3 "Installing the endpoint program"
  if [ -x /usr/local/bin/hysteria ]; then
    info "Already installed: $(/usr/local/bin/hysteria version 2>/dev/null | sed -n 's/^Version:[[:space:]]*//p' | head -1)"
  else
    bash <(curl -fsSL https://get.hy2.sh/) </dev/null >/tmp/sonar-hy2-install.log 2>&1 \
      || fail "The Hysteria2 installer failed (see /tmp/sonar-hy2-install.log)." "Check that the server can reach github.com, then run the command again."
    [ -x /usr/local/bin/hysteria ] || fail "Hysteria2 was not installed." "See /tmp/sonar-hy2-install.log."
    changed "installed /usr/local/bin/hysteria (official installer)"
  fi

  step 4 "Configuring the endpoint (local only, no port opened)"
  id sonar >/dev/null 2>&1 || { useradd --system --no-create-home --shell /usr/sbin/nologin sonar 2>/dev/null || useradd -r -M -s /sbin/nologin sonar; changed "created system user sonar"; }
  mkdir -p "$ETC" "$LIB"
  chmod 750 "$ETC"; chown root:sonar "$ETC"
  # Internal port: 2095 unless something that is not ours already holds it.
  HY_PORT="$(cat "$ETC/hy_port" 2>/dev/null || echo "$HY_PORT_DEFAULT")"
  holder="$(udp_holder "$HY_PORT")"
  if [ -n "$holder" ] && ! systemctl is-active --quiet sonar-edge; then
    for p in $(seq 2096 2199); do [ -z "$(udp_holder "$p")" ] && { HY_PORT=$p; break; }; done
    info "UDP $HY_PORT_DEFAULT is used by $holder; using local port $HY_PORT instead."
  fi
  echo "$HY_PORT" > "$ETC/hy_port"
  echo "$CERT_B64" | base64 -d > "$ETC/cert.pem"
  echo "$KEY_B64" | base64 -d > "$ETC/key.pem"
  cat > "$ETC/edge.yaml" <<EOF
# managed by Sonar (profile $PROFILE_ID)
listen: 127.0.0.1:$HY_PORT
tls:
  cert: $ETC/cert.pem
  key: $ETC/key.pem
auth:
  type: password
  password: "$HY_PASSWORD"
obfs:
  type: salamander
  salamander:
    password: "$OBFS_PASSWORD"
EOF
  chown root:sonar "$ETC/cert.pem" "$ETC/key.pem" "$ETC/edge.yaml"
  chmod 640 "$ETC/cert.pem" "$ETC/key.pem" "$ETC/edge.yaml"
  cat > /etc/systemd/system/sonar-edge.service <<EOF
[Unit]
Description=Sonar edge (local only)
After=network-online.target
Wants=network-online.target

[Service]
User=sonar
ExecStart=/usr/local/bin/hysteria server --config $ETC/edge.yaml
Restart=always
RestartSec=3
LimitNOFILE=65536

[Install]
WantedBy=multi-user.target
EOF
  changed "wrote $ETC/edge.yaml and sonar-edge.service"

  step 5 "Installing the Sonar helper"
  echo "$RELAY_B64" | base64 -d > "$LIB/sonar_link.py"
  chmod 755 "$LIB/sonar_link.py"
  cat > /etc/systemd/system/sonar-link.service <<EOF
[Unit]
Description=Sonar link
After=network-online.target sonar-edge.service
Wants=network-online.target

[Service]
ExecStart=/usr/bin/env python3 -I $LIB/sonar_link.py $HY_PORT 1
Restart=always
RestartSec=2
NoNewPrivileges=yes
ProtectHome=yes
ProtectSystem=full

[Install]
WantedBy=multi-user.target
EOF
  echo "$PROFILE_ID" > "$ETC/profile"
  echo "$SONAR_SCRIPTS_VERSION" > "$ETC/version"
  systemctl daemon-reload
  systemctl enable sonar-edge sonar-link >/dev/null 2>&1
  systemctl restart sonar-edge
  systemctl restart sonar-link
  changed "installed the Sonar helper and its service (enabled at boot)"

  step 6 "Applying network settings and firewall"
  sysctl_on
  info "Applied the network settings Sonar needs on this server."
  :
  firewall_open
  info "Firewall: $FW"

  step 7 "Self-test"
  cp -f "$0" "$SELF" 2>/dev/null && chmod 700 "$SELF"
  sleep 2
  systemctl is-active --quiet sonar-edge || { journalctl -u sonar-edge -n 15 --no-pager 2>/dev/null; fail "Hysteria2 did not start (log above)." "Copy everything and paste it into the Sonar app."; }
  systemctl is-active --quiet sonar-link || { journalctl -u sonar-link -n 15 --no-pager 2>/dev/null; fail "The Sonar relay did not start (log above)." "Copy everything and paste it into the Sonar app."; }

  echo
  echo "Changes made:"
  if [ ${#CHANGES[@]} -eq 0 ]; then echo "  none (already set up, services restarted)"; else for c in "${CHANGES[@]}"; do echo "  - $c"; done; fi
  echo "Undo everything: sudo sonar-server --uninstall"
  status_table
}

case "${1:-}" in
  --status) need_root; detect_os; status_table ;;
  --uninstall) detect_os; uninstall ;;
  --version) echo "$SONAR_SCRIPTS_VERSION" ;;
  ""|--install) install ;;
  *) echo "usage: $0 [--status|--uninstall|--version]"; exit 2 ;;
esac
